selector_to_html = {"a[href=\"#parse-vendor-performance-data\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.3 Parse vendor performance data<a class=\"headerlink\" href=\"#parse-vendor-performance-data\" title=\"Link to this heading\">#</a></h3><p>The purpose of this interface is to convert the raw results of the vendor Profiler into unified results that FlagPrism can read.</p><p>The raw results may come from memory data collected at runtime, or from files exported by vendor tools. When an external tool is used, the tool invocation and the result import must both be completed, and errors must be reported when execution fails.</p>", "a[href=\"#profiler\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.1 Profiler<a class=\"headerlink\" href=\"#profiler\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#collection-plan-vendorprofileplan\"]": "<h4 class=\"tippy-header\" style=\"margin-top: 0;\">Collection plan (VendorProfilePlan)<a class=\"headerlink\" href=\"#collection-plan-vendorprofileplan\" title=\"Link to this heading\">#</a></h4><p><code class=\"docutils literal notranslate\"><span class=\"pre\">makePlan()</span></code> generates the collection configuration <code class=\"docutils literal notranslate\"><span class=\"pre\">VendorProfilePlan</span></code> for this run according to the user request and the scope supported by the vendor.</p><p>The user request <code class=\"docutils literal notranslate\"><span class=\"pre\">VendorProfileOptions</span></code> contains:</p>", "a[href=\"#start-collection-and-mark-operators\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.2 Start collection and mark operators<a class=\"headerlink\" href=\"#start-collection-and-mark-operators\" title=\"Link to this heading\">#</a></h3><p>This stage is responsible for invoking the vendor Profiler, and adding markers at the start and end of Triton operators.</p><p>Implement the following interfaces:</p>", "a[href=\"#kernel-compilation-and-launch-requirements\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.2 Kernel compilation and launch requirements<a class=\"headerlink\" href=\"#kernel-compilation-and-launch-requirements\" title=\"Link to this heading\">#</a></h3><p>In addition to the C++ interfaces above, the chip compiler and launcher must also support:</p>", "a[href=\"#id1\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.3 Ascend implementation approach<a class=\"headerlink\" href=\"#id1\" title=\"Link to this heading\">#</a></h3><p>The Debugger Runtime on Ascend uses the following CANN interfaces:</p>", "a[href=\"#validation\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">6. Validation<a class=\"headerlink\" href=\"#validation\" title=\"Link to this heading\">#</a></h2><p>After adaptation, on the target chip, enter the FlagPrism repository root and run the unified operator acceptance test:</p>", "a[href=\"#debugger\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">5.2 Debugger<a class=\"headerlink\" href=\"#debugger\" title=\"Link to this heading\">#</a></h3><p>Existing FlagTree compiler callbacks and launch interfaces should be reused with priority; when a new backend has not yet been integrated, the corresponding compilation and launch integration should be completed on the FlagTree side, and the collection and parsing logic should be placed in FlagPrism.</p>", "a[href=\"#declare-capabilities-and-generate-the-collection-configuration\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.1 Declare capabilities and generate the collection configuration<a class=\"headerlink\" href=\"#declare-capabilities-and-generate-the-collection-configuration\" title=\"Link to this heading\">#</a></h3><p><code class=\"docutils literal notranslate\"><span class=\"pre\">VendorAdapter</span></code> is responsible for stating which metrics the vendor supports, and converting the user request into the collection configuration actually used in this run.</p><p>Implement the following 6 interfaces:</p>", "a[href=\"#device-runtime-interfaces\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">3.1 Device runtime interfaces<a class=\"headerlink\" href=\"#device-runtime-interfaces\" title=\"Link to this heading\">#</a></h3><p>Implement the following 11 interfaces:</p>", "a[href=\"#flagprism-profiler-and-debugger-chip-vendor-adaptation-requirements\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">FlagPrism Profiler and Debugger Chip Vendor Adaptation Requirements<a class=\"headerlink\" href=\"#flagprism-profiler-and-debugger-chip-vendor-adaptation-requirements\" title=\"Link to this heading\">#</a></h1><h2>1. Goal<a class=\"headerlink\" href=\"#goal\" title=\"Link to this heading\">#</a></h2><p>The environment preparation uses the FlagTree development container corresponding to the chip; the detailed steps are given in the user manual of that backend. The LLVM and SDK environment follows the configuration of the corresponding FlagTree container.</p><p>After the chip adaptation is complete, the following must be supported:</p>", "a[href=\"#correspondence-between-interfaces-and-code-files\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">5. Correspondence between interfaces and code files<a class=\"headerlink\" href=\"#correspondence-between-interfaces-and-code-files\" title=\"Link to this heading\">#</a></h2><p>The following code can be used as a reference. The Profiler files show the collection implementations of each vendor; the four Debugger Runtime Adapters are all located in <a class=\"reference external\" href=\"https://github.com/flagos-ai/FlagPrism/blob/main/Debugger/lib/Runtime/TransferEngine.cpp\">TransferEngine.cpp</a>, and can be found by the class names in the table.</p>", "a[href=\"#information-sources\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">1.1 Information sources<a class=\"headerlink\" href=\"#information-sources\" title=\"Link to this heading\">#</a></h3><p>The information in the current design is divided into three categories:</p>", "a[href=\"#goal\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">1. Goal<a class=\"headerlink\" href=\"#goal\" title=\"Link to this heading\">#</a></h2><p>The environment preparation uses the FlagTree development container corresponding to the chip; the detailed steps are given in the user manual of that backend. The LLVM and SDK environment follows the configuration of the corresponding FlagTree container.</p><p>After the chip adaptation is complete, the following must be supported:</p>", "a[href=\"#ascend-implementation-approach\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">2.4 Ascend implementation approach<a class=\"headerlink\" href=\"#ascend-implementation-approach\" title=\"Link to this heading\">#</a></h3><p>The implementation approach on Ascend is as follows:</p>", "a[href=\"#profiler-adaptation-interfaces\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">2. Profiler adaptation interfaces<a class=\"headerlink\" href=\"#profiler-adaptation-interfaces\" title=\"Link to this heading\">#</a></h2><p>Profiler adaptation is divided into three steps:</p>", "a[href=\"#debugger-adaptation-interfaces\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">3. Debugger adaptation interfaces<a class=\"headerlink\" href=\"#debugger-adaptation-interfaces\" title=\"Link to this heading\">#</a></h2><h3>3.1 Device runtime interfaces<a class=\"headerlink\" href=\"#device-runtime-interfaces\" title=\"Link to this heading\">#</a></h3><p>Implement the following 11 interfaces:</p>", "a[href=\"#error-handling-requirements\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">4. Error handling requirements<a class=\"headerlink\" href=\"#error-handling-requirements\" title=\"Link to this heading\">#</a></h2>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
